  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'tshwane-bronkhorstspruit-water-illness-da-case-2026-10-19',
  'Tshwane probes Bronkhorstspruit illness cluster, DA opens case over water',
  'Utilities', '2026-10-19', 'Caxton Network News', 'https://www.citizen.co.za/network-news/lnn/article/da-opens-criminal-case-over-bronkhorstspruit-water-crisis/',
  'Tshwane is investigating 140 to 160 diarrhoea cases near Bronkhorstspruit as the DA opens a criminal case over the area''s water safety.',
  'Health officials in Tshwane are trying to pin down what triggered a wave of stomach illness around Bronkhorstspruit, after doctors logged between 140 and 160 cases of diarrhoea and similar symptoms over six days from 7 to 12 October. Bronkhorstspruit Hospital has handled most of the patients, while a smaller number turned up at Wilgers, at Steve Biko Academic, and at Mamelodi. No deaths have been reported. The city says contaminated water is one possible cause but has not confirmed this, and lab results from patients'' blood and stool samples have not yet come back.

Officials have ramped up checks on water quality at the Bronkhorstspruit plant itself and further along the pipe network that feeds the surrounding suburbs, while the investigation continues. In the meantime, residents in the affected area are being told to rely on alternative safe water, including municipal tankers that draw supply from Cullinan, outside the affected network, and are disinfected daily. Anyone who keeps having diarrhoea or vomiting, runs a fever, feels unusually weak, or shows other signs of being dehydrated should get medical help, particularly children and elderly residents.

On 19 October, the Democratic Alliance laid a criminal complaint naming the municipality at the Pretoria Central police station, accusing officials of letting safe drinking-water standards slip at the plant. The party has asked the city to release its water-quality and chlorination records and called for a forensic investigation into recent spending on water tankers versus infrastructure repairs. ActionSA councillor Cobus Coetzee, who represents the area, disputed the DA''s account, saying the plant has had recent operational upgrades and further improvements are budgeted for the new financial year. The city had not responded to questions on the allegations by the time the case was reported.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/network-news/lnn/article/da-opens-criminal-case-over-bronkhorstspruit-water-crisis/", "https://www.ewn.co.za/tshwane-probing-stomach-related-illnesses-in-bronkhorstspruit-surrounding-areas/", "https://www.timeslive.co.za/news/south-africa/2026-10-16-tshwane-probes-cluster-of-stomach-related-illnesses-in-bronkhorstspruit/"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'pretoria-water-saving-el-nino-heat-2026-10-19',
  'Pretoria residents urged to save water as strong El Nino looms',
  'Utilities', '2026-10-19', 'Rekord', 'https://www.citizen.co.za/rekord/uncategorized/2026/10/19/pretoria-residents-urged-to-save-water-as-el-nino-and-high-temperatures-strain-supply/',
  'Pretoria residents are urged to cut water use as a strengthening El Nino threatens drier, hotter conditions and strain on supply.',
  'Pretoria residents are being urged to cut back on water use as rising temperatures and persistent demand put pressure on the city''s supply network, even where dam levels remain adequate. High demand in hot weather can draw down reservoirs quickly, and because pumps across the distribution network run on electricity, power outages can add further strain and disrupt supply to homes.

The warning comes as the South African Weather Service reports that a strong El Nino has developed in the Pacific Ocean and is expected to strengthen further, with forecasters describing the event as potentially "the strongest event in living memory." Its outlook points to a drier, hotter spell settling over most of the country for the rest of this year and running into early 2027, raising the risk of more frequent heatwaves and extra strain on water supplies.

Residents are advised to make small changes at home: running washing machines and dishwashers only with full loads, keeping showers brief, using a bucket rather than a hose for outdoor cleaning, and fixing dripping taps and leaking pipes. A standard tap or shower outlet delivers about 10 litres of water a minute, so even small reductions in time add up. In the garden, residents are encouraged to water manually rather than on automatic timers, water deeply but less often, and choose the cooler parts of the day, while households are also urged to keep an eye on their water meters to catch unexpected leaks early.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/rekord/uncategorized/2026/10/19/pretoria-residents-urged-to-save-water-as-el-nino-and-high-temperatures-strain-supply/", "https://www.sanews.gov.za/south-africa/saws-warns-very-strong-el-nino-and-hotter-drier-spring-conditions"]',
  'agent'
);
